import{_ as o,r as s,o as p,c as i,e as t,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Navigation - October CMS - 3.x","titleTemplate":false,"description":"Learn how to include new menu items in the backend panel.","frontmatter":{"subtitle":"Learn how to include new menu items in the backend panel."},"headers":[{"level":2,"title":"Navigation Counters","slug":"navigation-counters","link":"#navigation-counters","children":[]},{"level":2,"title":"Item Display Types","slug":"item-display-types","link":"#item-display-types","children":[]},{"level":2,"title":"Extending the Backend Menu","slug":"extending-the-backend-menu","link":"#extending-the-backend-menu","children":[]}],"relativePath":"3.x/extend/backend/navigation.md","filePath":"3.x/extend/backend/navigation.md"}'),r={name:"3.x/extend/backend/navigation.md"};function u(g,n,d,k,m,h){const a=s("pre-heading"),e=s("post-heading");return p(),i("div",null,[t(a),n[0]||(n[0]=c("h1",null,"Navigation",-1)),t(e),n[1]||(n[1]=l(`<p>Plugins can extend the backend navigation menus by overriding the <code>registerNavigation</code> method of the <a href="./../extending.html">plugin registration file</a>. This section shows you how to add menu items to the backend navigation area. The following is an example of registering a top-level navigation menu item with two sub-menu items.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerNavigation</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-pencil&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>

            <span class="token string single-quoted-string">&#39;sideMenu&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Posts&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Categories&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>When you register the backend navigation you can use <a href="./../system/localization.html">localization strings</a> for the <code>label</code> values. Backend navigation can also be controlled by the <code>permissions</code> values and correspond to defined <a href="./permissions.html">backend user permissions</a>. The order in which the backend navigation appears on the overall navigation menu items, is controlled by the <code>order</code> value. Higher numbers mean that the item will appear later on in the order of menu items while lower numbers mean that it will appear earlier on.</p><p>To make the sub-menu items visible, you may set the navigation context in the <a href="./../system/controllers.html">backend controller</a> using the <code>BackendMenu::setContext</code> method. This will make the parent menu item active and display the children in the side menu.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>specifies the menu label localization string key, required.</td></tr><tr><td><strong>order</strong></td><td>a numerical weight when determining the display order.</td></tr><tr><td><strong>icon</strong></td><td>an icon name from the <a href="./../../element/available-icons.html">October CMS icon collection</a>, optional.</td></tr><tr><td><strong>iconSvg</strong></td><td>an SVG icon to be used in place of the standard icon, the SVG icon should be a rectangle and can support colors, optional.</td></tr><tr><td><strong>url</strong></td><td>the URL the menu item should point to (eg. <code>Backend::url(&#39;author/plugin/controller/action&#39;)</code>, required.</td></tr><tr><td><strong>counter</strong></td><td>a numeric value to output near the menu icon. The value should be a number or a callable returning a number, optional.</td></tr><tr><td><strong>counterLabel</strong></td><td>a string value to describe the numeric reference in counter, optional.</td></tr><tr><td><strong>attributes</strong></td><td>an associative array of attributes and values to apply to the menu item, optional.</td></tr><tr><td><strong>permissions</strong></td><td>an array of permissions the backend user must have in order to view the menu item (Note: direct access of URLs still requires separate permission checks), optional.</td></tr><tr><td><strong>sideMenu</strong></td><td>an array of sub-menu items sharing the same configuration as parent menu items, optional.</td></tr><tr><td><strong>itemType</strong></td><td>specifies a display type for the item, sub-menu items only. Supported: <code>primary</code>, <code>link</code>, <code>ruler</code>, <code>section</code>. Default: <code>link</code>.</td></tr></tbody></table></div><p>The following are system generated value and are not provided when registering the navigation items.</p><div class="table"><table tabindex="0"><thead><tr><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><strong>code</strong></td><td>a string value that acts as an unique identifier for that menu option.</td></tr><tr><td><strong>owner</strong></td><td>a string value that specifies the menu items owner plugin or module in the format &quot;Author.Plugin&quot;.</td></tr></tbody></table></div><h2 id="navigation-counters"><a href="#navigation-counters" class="header-anchor">#</a> Navigation Counters</h2><p>Navigation items support specifying a counter to indicate that there are items that require attention. These properties are available to parent and child menu items alike. Use the <strong>counter</strong> and <strong>counterLabel</strong> to show a numeric counter.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// ...</span>
    <span class="token string single-quoted-string">&#39;counter&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MyMenuCounterService</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;getCounterMethod&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;counterLabel&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Label describing a dynamic menu counter&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="item-display-types"><a href="#item-display-types" class="header-anchor">#</a> Item Display Types</h2><p>Sub-menu items support different display types using the <code>itemType</code> property, including user-interface elements. Set the type to <code>section</code> to display a navigation section. Prefixing the key name with an underscore (<code>_</code>) is a good way to communicate that it is a UI element.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;_section1&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;section&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Advanced&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>It might be useful to combine a section with a navigation divider placed above it. Set the type to <code>ruler</code> to display a divider.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;_ruler1&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ruler&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>To display a call to action, set the type to <code>primary</code> to display the link as a primary button.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;people_create&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;New Person&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-plus&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/people/create&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;primary&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="extending-the-backend-menu"><a href="#extending-the-backend-menu" class="header-anchor">#</a> Extending the Backend Menu</h2><p>The <code>backend.menu.extendItems</code> <a href="./../extending.html">event listener</a> can be used to modify the existing navigation items, after the system and plugins have registered their navigation items. The event returns a navigation <code>$manager</code> instance that supports the following methods.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>addMainMenuItems($owner, $definitions)</strong></td><td>Add or update a main menu definition</td></tr><tr><td><strong>getMainMenuItem($owner, $code)</strong></td><td>Retrieve an existing main menu definition</td></tr><tr><td><strong>removeMainMenuItem($owner, $code)</strong></td><td>Delete an existing main menu definition</td></tr><tr><td><strong>addSideMenuItems($owner, $code, $definitions)</strong></td><td>Add or update a side menu definition</td></tr><tr><td><strong>getSideMenuItem($owner, $code, $sideCode)</strong></td><td>Retrieve an existing side menu definition</td></tr><tr><td><strong>removeSideMenuItem($owner, $code, $sideCode)</strong></td><td>Delete an existing side menu definition</td></tr></tbody></table></div><p>When retrieving a menu item, the object supports method chaining to update its properties. The following example will replace the label for the Editor with <strong>Code Editor</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">getMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;October.Editor&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;editor&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">label</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Code Editor&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The next example will change the label to <strong>News</strong> and add a <strong>9</strong> counter to the Acme Blog plugin.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">getMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">getSideMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">label</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;News&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">counter</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Similarly, we can remove the menu items using the same event. The following example will remove all items, remove a single item, and remove multiple items, respectively.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeSideMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeSideMenuItems</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;categories&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,26))])}const f=o(r,[["render",u]]);export{v as __pageData,f as default};
